                    Ok(shared) => shared,
                    Err(error) => {
                        self.closures.reject_after_error();
                        return Err(error);
                    }
                };
                #[cfg(test)]
                app_census::acquired();
                self.closures.insert(function, node, budget, || shared)?;
                #[cfg(test)]
                app_census::published();
                continue;
            }
