        assert_eq!(
            current.closure(&function, roots[0], &mut budget),
            Err(Diagnostic::io("SPX-H006", String::new()))
        );
        assert_eq!(current_metrics().allocated, at);
        assert!(current.closures.get(&roots[0]).is_none());
