                    .map_err(|reason| permit.refuse(reason))?
            } || !matches!(
                function.cleanup_plan.schema,
                crate::cleanup_plan::CLEANUP_PLAN_SCHEMA_V18
                    | crate::cleanup_plan::CLEANUP_PLAN_SCHEMA_V19
            ))
        {
