            assert!(old.message.contains(if profile {
                "module-local primitive context"
            } else {
                "not held by its current context"
            }));
            assert!(matches!(
                current.validate_scalar_paid(&program.functions[0]),
                Err(expression_facts::errors::EngineError::Failed)
            ));
