            collections::prepay(
                program,
                function,
                collections::type_key_bytes(&parameter.ty, function, budget)?,
                budget,
            )?;
        }
        if !flat_records::admitted(program, &parameter.ty, function, budget)? {
            return Err(refusal(
                function,
                budget,
                "selected parameter type is outside direct records",
            ));
