                                        latch,
                                        crate::hir::LoopLatchKind::SourceForStep {
                                            kind: crate::hir::SourceForKind::Copy,
                                            ..
                                        }
                                    ) {
                                        let ResolvedExprKind::Block { statements, .. } = &body.kind
                                        else {
