                        scrutinee, arms, ..
                    } => {
                        if matches!(scrutinee.ty, ResolvedType::Nominal { .. }) {
                            return Err(refusal(
                                function,
                                budget,
                                "selected direct records do not admit owning or destructuring matches",
                            ));
