    pub(super) fn build(
        function: &'a ResolvedFunction,
        storage: &Storage,
        walker: &mut Walker<'a>,
    ) -> Result<Self, Failure> {
        storage
            .reserve(std::mem::size_of::<Self>() + std::mem::size_of::<Result<Self, Failure>>())?;
