                | ResolvedExprKind::VecConstructor { statements, .. } = &expression.kind
                {
                    definitions = definitions
                        .checked_add(
                            statements
                                .iter()
                                .filter(|statement| {
                                    matches!(statement, ResolvedStatement::Let { .. })
                                })
                                .count(),
                        )
                        .ok_or_else(|| {
                            Failure::semantic(
                                "borrowed byte traversal census binding count overflows",
                            )
