    let fixture = Census::acquire(&program, sum).unwrap();
    let root = fixture
        .rows
        .iter()
        .min_by_key(|row| row.start)
        .unwrap()
        .shape
        .root;
    drop(fixture);
    for warm in [false, true] {
        let ((((), metrics), remaining), refused, used, first) =
