            assert_eq!(refused, !ok);
            assert_eq!(first.is_some(), !ok);
            assert!(
                !observed.invalid && observed.live == 0 && observed.allocated == observed.freed
            );
            assert!(observed.allocated <= used && observed.highwater <= used);
            if limit == 0 {
                assert_eq!(observed.allocated, 0);
            }
        }
    }
}

